/*
 * RING_$PROC2_CLEANUP - close every ring channel an address space holds
 *
 * Original address: 0x00E76A42
 * Size: 234 bytes (0x00E76A42 .. 0x00E76B2B)
 * Generated by: Claude Opus 5.5
 *
 * The proc2_cleanup slot of RING_$CTL's driver block (0x00E86938).
 * NET_IO_$FREE_ASID calls the slot with the port's socket cell by address
 * (for the ring port, the unit number) and the dying address space's id by
 * value (net_io/net_io.h).  Frame: (0x8,A6) unit_ptr, (0xC,A6) asid word.
 * A5 = RING_$CTL (0xE86400).
 *
 * Blocks:
 *   0x00E76A58-0x00E76A5C  unit above 1: nothing happens (no status)
 *   0x00E76A60-0x00E76A70  u = &RING_$CTL.units[unit]; a unit whose
 *                          RING_UNIT_STARTED bit (bit 0 of +0x31) is clear:
 *                          nothing happens
 *   0x00E76A74-0x00E76A7E  enter rx_exclusion (+0x4C)
 *   0x00E76A80-0x00E76AF8  channels 1..10 (`moveq #0x9,D4' / dbf): an open
 *                          channel (flags byte negative) whose asid word
 *                          equals asid is closed - flags cleared, its socket
 *                          closed unless it is RING_OS_SOCKET_ID, every
 *                          packet-type entry it owns dropped (the same
 *                          last-entry-moves-down loop as RING_$SVC_CLOSE,
 *                          0x00E76AB2-0x00E76AF0), and counted
 *   0x00E76AFC-0x00E76B1C  leave rx_exclusion; open_count -= the count
 *                          under tx_exclusion (+0x34)
 *
 * Quirks reproduced:
 *   - Only 10 of a packet-type entry's 12 bytes move (0x00E76ADA-0x00E76ADE).
 *   - `movea.l A0,A0' at 0x00E76A8A is a no-op.
 */

#include "ring/ring_internal.h"

void RING_$PROC2_CLEANUP(uint16_t *unit_ptr, uint16_t asid)
{
    ring_unit_t *u;                     /* A2 */
    ring_channel_t *chan;               /* A3 + 0x5A */
    int16_t closed;                     /* D3 */
    int16_t n;                          /* D4 */
    uint16_t ch;                        /* D5 */
    uint16_t i;                         /* D0 */
    ring_pkt_type_t *dst;               /* A4 */
    ring_pkt_type_t *src;               /* A1 */

    /* 0x00E76A58-0x00E76A5C */
    if (*unit_ptr > 1) {
        return;
    }

    /* 0x00E76A60-0x00E76A70 */
    u = &RING_$CTL.units[*unit_ptr];
    if ((u->state_flags & RING_UNIT_STARTED) == 0) {
        return;
    }

    /* 0x00E76A74-0x00E76A7E */
    ML_$EXCLUSION_START(&u->rx_exclusion);

    /* 0x00E76A80-0x00E76AF8 */
    closed = 0;
    ch = 1;
    for (n = 9; n >= 0; n--) {
        chan = &RING_UNIT_CHANNEL(u, ch);
        if (chan->flags < 0 && (uint16_t)chan->asid == asid) {
            /* 0x00E76A98 */
            chan->flags = 0;
            /* 0x00E76A9C-0x00E76AB0 */
            if (chan->socket_id != RING_OS_SOCKET_ID) {
                SOCK_$CLOSE((uint16_t)chan->socket_id);
            }
            /* 0x00E76AB2-0x00E76AF0 */
            i = 1;
            while (i <= u->pkt_type_cnt) {
                if ((uint16_t)RING_UNIT_PKT_TYPE(u, i).channel == ch) {
                    dst = &RING_UNIT_PKT_TYPE(u, i);
                    src = &RING_UNIT_PKT_TYPE(u, u->pkt_type_cnt);
                    dst->low = src->low;
                    dst->high = src->high;
                    dst->channel = src->channel;
                    u->pkt_type_cnt--;
                } else {
                    i++;
                }
            }
            /* 0x00E76AF2 */
            closed++;
        }
        /* 0x00E76AF4-0x00E76AF8 */
        ch++;
    }

    /* 0x00E76AFC-0x00E76B1C */
    ML_$EXCLUSION_STOP(&u->rx_exclusion);
    ML_$EXCLUSION_START(&u->tx_exclusion);
    u->open_count -= closed;
    ML_$EXCLUSION_STOP(&u->tx_exclusion);
}
